class Solution {
public:
    vector<int> delayedCount(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> ans(n), freq(100001, 0);
        for (int i = n - 1; i >= 0; --i) {
            if (i + k + 1 < n) ++freq[nums[i + k + 1]];
            ans[i] = freq[nums[i]];
        }
        return ans;
    }
};
